package com.example.recon;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class ReconciliationClient{private final String b;private final HttpClient h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();public ReconciliationClient(String b){this.b=b.replaceAll("/$","");}public String score()throws Exception{var q=HttpRequest.newBuilder(URI.create(b+"/v1/risk")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"payment_id\":\"P-DEMO\",\"amount\":500,\"age_hours\":3,\"currency_mismatch\":0,\"reference_similarity\":0.9,\"counterparty_risk\":0.1}")).build();var r=h.send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new IllegalStateException(r.body());return r.body();}public static void main(String[]a)throws Exception{System.out.println(new ReconciliationClient(a.length>0?a[0]:"http://127.0.0.1:8000").score());}}
